cat << 'INNER_EOF' > /tmp/update_all_live.py
import base64

pm_b64 = ""
pg_b64 = ""
routes_b64 = ""

with open("src/components/CaptivePortal/PaymentModal.tsx", "w") as f:
    f.write(base64.b64decode(pm_b64).decode('utf-8'))

with open("server/paymentGateway.ts", "w") as f:
    f.write(base64.b64decode(pg_b64).decode('utf-8'))

with open("server/routes.ts", "w") as f:
    f.write(base64.b64decode(routes_b64).decode('utf-8'))

print("UPDATED_FILES_SUCCESSFULLY")
INNER_EOF
python3 /tmp/update_all_live.py
rm -f /tmp/update_all_live.py
npm run build
pm2 restart all --update-env
pm2 save
